import json
with open('/app/resources/treasury_bulletin_1947_02.json') as f:
    data = json.load(f)

# Search for any 1938 data
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            search(v, f'{path}[{i}]')
    elif isinstance(obj, str):
        if '1938' in obj:
            print(f'Found at {path}: {obj[:200]}')

search(data)
